replace_once(
    recovery,
    "        let mut control_fault = None;\n",
    "        let mut release_fault = None;\n        let mut control_fault = None;\n",
)
replace_once(
    recovery,
    """                    if needs_resolution {\n                        let resolved = self.registry.resolve_release(agent_id, &lease.release_id);\n                        self.bind_adopted_release(agent_id, slot, record, resolved, now)?;\n                    }\n""",
    """                    if needs_resolution {\n                        let resolved = self.registry.resolve_release(agent_id, &lease.release_id);\n                        if let Err(error) =\n                            self.bind_adopted_release(agent_id, slot, record, resolved, now)\n                        {\n                            release_fault = Some(error);\n                        }\n                    }\n""",
)
replace_once(
    recovery,
    """                // Install the exact adopted handle before any fallible control\n                // call. Failed signals retain both ownership and a bounded retry.\n                slot.pending_control = recovery_control;\n                control_fault =\n                    pending::apply_to_slot(agent_id, slot, now, self.config.stop_grace).err();\n                if record.lifecycle.lifecycle == AgentLifecycle::Running {\n                    // A daemon can die after committing the Running lifecycle but before\n                    // appending the matching release-state revision. The lease and exact\n                    // agentd handshake prove the live release; close that crash window now.\n                    self.persist_release_state(agent_id, slot)?;\n                }\n""",
    """                if release_fault.is_none() {\n                    // Install the exact adopted handle before any fallible control\n                    // call. Failed signals retain both ownership and a bounded retry.\n                    slot.pending_control = recovery_control;\n                    control_fault =\n                        pending::apply_to_slot(agent_id, slot, now, self.config.stop_grace).err();\n                    if record.lifecycle.lifecycle == AgentLifecycle::Running {\n                        // A daemon can die after committing the Running lifecycle but before\n                        // appending the matching release-state revision. The lease and exact\n                        // agentd handshake prove the live release; close that crash window now.\n                        self.persist_release_state(agent_id, slot)?;\n                    }\n                }\n""",
)
replace_once(
    recovery,
    """        // A main-process signal failure must not skip companion adoption.\n        self.recover_matrix_companion(agent_id, slot, record, now)?;\n        if let Some(error) = control_fault {\n            return Err(error);\n        }\n        Ok(())\n""",
    """        // Release conversion can fail only after exact main-process adoption.\n        // That fault must not skip ownership/containment of an existing companion.\n        let matrix_fault = if release_fault.is_some() {\n            self.contain_matrix_companion_after_main_recovery_fault(\n                agent_id,\n                slot,\n                record,\n                now,\n                \"main release recovery was rejected\",\n            )\n            .err()\n        } else {\n            self.recover_matrix_companion(agent_id, slot, record, now)\n                .err()\n        };\n        if let Some(error) = release_fault {\n            if let Some(matrix) = matrix_fault {\n                slot.event(\n                    record.lifecycle.generation,\n                    SupervisorEventKind::DriverFault(bounded_message(matrix.to_string())),\n                );\n            }\n            return Err(error);\n        }\n        if let Some(error) = control_fault {\n            if let Some(matrix) = matrix_fault {\n                slot.event(\n                    record.lifecycle.generation,\n                    SupervisorEventKind::DriverFault(bounded_message(matrix.to_string())),\n                );\n            }\n            return Err(error);\n        }\n        if let Some(error) = matrix_fault {\n            return Err(error);\n        }\n        Ok(())\n""",
)

matrix = ROOT / "codex-rs/hepta-supervisor/src/matrix.rs"
marker = """    pub(crate) fn recover_matrix_companion(\n"""
helper = """    pub(crate) fn contain_matrix_companion_after_main_recovery_fault(\n        &mut self,\n        agent_id: &AgentId,\n        slot: &mut AgentSlot<D::Process>,\n        record: &AgentRecord,\n        now: Instant,\n        reason: &str,\n    ) -> Result<(), SupervisorError> {\n        if slot.matrix.runtime.is_some() {\n            if let Some(runtime) = slot.matrix.runtime.as_mut() {\n                runtime.healthy = false;\n                runtime.fenced = true;\n            }\n            let result = self.kill_matrix_now(agent_id, slot);\n            self.degrade_matrix(\n                agent_id,\n                slot,\n                record.lifecycle.generation,\n                reason.to_string(),\n                now,\n            );\n            slot.matrix.retry_at = None;\n            slot.matrix.restart_after_exit = false;\n            slot.matrix.restart_exhausted = true;\n            return result;\n        }\n\n        let Some(lease) = read_matrix_lease(record.layout.matrixd_process_lease())? else {\n            return Ok(());\n        };\n        if lease.agent_id != *agent_id {\n            return Err(SupervisorError::CorruptLease(format!(\n                \"Matrix lease identity differs from agent {agent_id}\"\n            )));\n        }\n        let spec = MatrixAdoptSpec {\n            agent_id: agent_id.clone(),\n            agent_generation: lease.attached_agent_generation,\n            binding_revision: lease.binding_revision,\n            binding_digest: lease.binding_digest.clone(),\n            release_id: lease.release_id.clone(),\n            process_incarnation: lease.process_incarnation.clone(),\n            plane_epoch: lease.plane_epoch,\n            control_socket: record.layout.matrixd_control_socket().to_path_buf(),\n            identity: lease.identity.clone(),\n        };\n        match self\n            .driver\n            .adopt_matrixd(&spec)\n            .map_err(|error| driver_error(agent_id, error))?\n        {\n            Adoption::Adopted(process) => {\n                slot.matrix.configured = true;\n                slot.matrix.runtime = Some(MatrixRuntime {\n                    process,\n                    identity: lease.identity,\n                    attached_agent_generation: lease.attached_agent_generation,\n                    release_id: lease.release_id,\n                    binding_revision: lease.binding_revision,\n                    binding_digest: lease.binding_digest,\n                    process_incarnation: lease.process_incarnation,\n                    plane_epoch: lease.plane_epoch,\n                    phase: MatrixRuntimePhase::Stopping { deadline: now },\n                    healthy: false,\n                    fenced: true,\n                });\n                let result = self.kill_matrix_now(agent_id, slot);\n                self.degrade_matrix(\n                    agent_id,\n                    slot,\n                    record.lifecycle.generation,\n                    reason.to_string(),\n                    now,\n                );\n                slot.matrix.retry_at = None;\n                slot.matrix.restart_after_exit = false;\n                slot.matrix.restart_exhausted = true;\n                slot.event(\n                    record.lifecycle.generation,\n                    SupervisorEventKind::MatrixOrphanRejected,\n                );\n                result\n            }\n            Adoption::Missing => {\n                remove_matrix_lease(record.layout.matrixd_process_lease(), &lease)?;\n                self.degrade_matrix(\n                    agent_id,\n                    slot,\n                    record.lifecycle.generation,\n                    format!(\"{reason}; Matrix companion is missing\"),\n                    now,\n                );\n                slot.matrix.retry_at = None;\n                slot.matrix.restart_after_exit = false;\n                slot.matrix.restart_exhausted = true;\n                slot.event(\n                    record.lifecycle.generation,\n                    SupervisorEventKind::MatrixOrphanMissing,\n                );\n                Ok(())\n            }\n            Adoption::Rejected => {\n                // Exact process identity was not proven, so the stale lease is\n                // retained as a fail-closed quarantine instead of authorizing a\n                // replacement or signalling a possibly reused PID.\n                self.degrade_matrix(\n                    agent_id,\n                    slot,\n                    record.lifecycle.generation,\n                    format!(\"{reason}; Matrix companion identity is unproven\"),\n                    now,\n                );\n                slot.matrix.retry_at = None;\n                slot.matrix.restart_after_exit = false;\n                slot.matrix.restart_exhausted = true;\n                slot.event(\n                    record.lifecycle.generation,\n                    SupervisorEventKind::MatrixOrphanRejected,\n                );\n                Err(SupervisorError::CorruptLease(\n                    \"unproven Matrix adoption retained its lease for operator reconciliation\"\n                        .to_string(),\n                ))\n            }\n        }\n    }\n\n"""
text = matrix.read_text(encoding="utf-8")
if text.count(marker) != 1:
    raise SystemExit(f"{matrix}: recovery marker count {text.count(marker)}")
matrix.write_text(text.replace(marker, helper + marker, 1), encoding="utf-8")

containment = ROOT / "codex-rs/hepta-supervisor/src/matrix_containment_tests.rs"
with containment.open("a", encoding="utf-8") as stream:
    stream.write("""\n#[test]\nfn main_recovery_fault_contains_owned_companion_before_returning() -> Result<()> {\n    let mut fixture = Fixture::new()?;\n    let now = Instant::now();\n    let record = fixture.registry.load()?.agents[&fixture.agent].clone();\n    fixture.supervisor.contain_matrix_companion_after_main_recovery_fault(\n        &fixture.agent,\n        &mut fixture.slot,\n        &record,\n        now,\n        \"injected main release recovery fault\",\n    )?;\n    assert_eq!(fixture.companion.lock().expect(\"companion\").kills, 1);\n    assert_eq!(fixture.main.lock().expect(\"main\").kills, 0);\n    let runtime = fixture.slot.matrix.runtime.as_ref().expect(\"retained companion\");\n    assert!(runtime.fenced && !runtime.healthy);\n    assert!(matches!(runtime.phase, MatrixRuntimePhase::Killing));\n    assert!(fixture.slot.matrix.restart_exhausted);\n    assert!(fixture.slot.matrix.retry_at.is_none());\n    assert_eq!(fixture.companion.lock().expect(\"companion\").drops, 0);\n    Ok(())\n}\n""")
